function header(req,name){return String(req.headers?.[name]||req.headers?.[name.toLowerCase()]||'');}
function clampName(user={}){return String([user.first_name,user.last_name].filter(Boolean).join(' ')||user.username||'Игрок').slice(0,80);}
function pairUser(id){return [OWNER_ID,PARTNER_ID].includes(String(id||''));}
function startCode(value=''){const m=String(value||'').match(/^night_([A-Z2-9]{6})$/i);return m?m[1].toUpperCase():'';}
function sendJson(res,status,data){const body=JSON.stringify(data);res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','content-length':Buffer.byteLength(body)});res.end(body);}
function sendHtml(res,body){const payload=Buffer.from(body,'utf8');res.writeHead(200,{'content-type':'text/html; charset=utf-8','content-language':'ru-RU','cache-control':'no-store, no-transform','x-content-type-options':'nosniff','content-length':payload.length});res.end(payload);}
async function readJson(req){return new Promise((resolve,reject)=>{let total=0,chunks=[];req.on('data',c=>{total+=c.length;if(total>MAX_BODY){reject(new Error('BODY_TOO_LARGE'));req.destroy();return;}chunks.push(c);});req.on('end',()=>{if(!chunks.length)return resolve({});try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));}catch{reject(new Error('BAD_JSON'));}});req.on('error',reject);});}
function timeout(promise,ms,code='NIGHT_V2_TIMEOUT'){let timer;return Promise.race([Promise.resolve(promise).finally(()=>clearTimeout(timer)),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(code)),ms);})]);}

