async function saveReaderPosition(page,sceneKey){try{const data=initData();if(!data)return;await fetch('/night/api/reader-progress',{method:'POST',headers:{'content-type':'application/json',...authHeaders()},body:JSON.stringify({page,sceneKey})})}catch{}}async function ensureReaderMedia(page,key,mode){if(!page?.media?.prompt||!key||readerMediaCache.has(key)||readerMediaPending.has(key))return;readerMediaPending.add(key);try{const data=initData();if(!data)return;const r=await fetch('/night/api/visual',{method:'POST',headers:{'content-type':'application/json',...authHeaders()},body:JSON.stringify({theme:uiTheme,mode:(mode==='story_final'||mode==='story_waiting_final')?'story_final':'story_scene',variant:'BOOK_PAGE: '+String(page.media.prompt||''),visualKey:key})});const j=await r.json();if(j?.ok&&j.image){readerMediaCache.set(key,j.image);if(state?.mode===mode)renderEpisodeReader(mode)}}catch{}finally{readerMediaPending.delete(key)}}
async function novelPage(page=1){clearTimeout(poll);const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),35000);try{const data=initData();if(!data)throw new Error('TELEGRAM_AUTH_MISSING');const r=await fetch('/night/api/novel-page',{method:'POST',headers:{'content-type':'application/json',...authHeaders()},body:JSON.stringify({page}),signal:ctl.signal});const raw=await r.text();let d;try{d=JSON.parse(raw)}catch{throw new Error('NIGHT_RESPONSE_INVALID')}if(!r.ok||!d.ok)throw new Error(d.error||'REQUEST_FAILED');state=d.state;render();return d}finally{clearTimeout(timer)}}
async function ensureLinearNovelImage(){const p=state?.page||{},n=state?.novel||{};if(!p.page_no||!n.id||!String(p.media_prompt||'').trim())return;const key=n.id+':'+p.page_no;if(linearNovelImageKey===key&&readerMediaCache.has('linear:'+key))return;linearNovelImageKey=key;try{const data=initData();if(!data)return;const r=await fetch('/night/api/novel-visual',{method:'POST',headers:{'content-type':'application/json',...authHeaders()},body:JSON.stringify({novelId:n.id,page:p.page_no})});const j=await r.json();if(j?.ok&&j.image){readerMediaCache.set('linear:'+key,j.image);if(state?.mode==='linear_novel'&&linearNovelImageKey===key)renderLinearNovel()}}catch{}}
function renderLinearNovel(){const n=state.novel||{},p=state.page||{},pageNo=Number(p.page_no)||1,total=Number(n.total_pages)||100,key='linear:'+n.id+':'+pageNo,img=readerMediaCache.get(key)||'';if(!img&&String(p.media_prompt||'').trim())void ensureLinearNovelImage();const progress=Math.max(1,Math.min(100,Math.round((pageNo/total)*100)));root.innerHTML='<section class="readerBook linearNovel"><div class="readerChrome"><span>'+esc(n.title||'РОМАН')+'</span><span>'+pageNo+' / '+total+'</span><div class="readerProgress"><i style="width:'+progress+'%"></i></div></div>'+(img?'<div class="readerMedia"><img src="'+esc(img)+'" alt=""></div>':'')+'<article class="readerPage '+(img?'hasMedia':'')+'"><div class="readerKicker">'+esc(p.chapter_title||'ГЛАВА '+(p.chapter_no||''))+'</div>'+(p.page_title?'<h1 class="readerTitle">'+esc(p.page_title)+'</h1>':'')+'<div class="readerText">'+esc(p.body||'')+'</div></article><div class="readerNav"><button class="readerArrow" id="novelPrev" '+(pageNo<=1?'disabled':'')+'>‹</button><div class="readerCount">СТРАНИЦА '+pageNo+' ИЗ '+total+'</div><button class="readerArrow" id="novelNext" '+(pageNo>=total?'disabled':'')+'>›</button></div></section>';bind('#novelPrev',safe(()=>novelPage(pageNo-1)));bind('#novelNext',safe(()=>novelPage(pageNo+1)));const shell=root.querySelector('.readerBook');if(shell){shell.addEventListener('touchstart',e=>{readerTouchX=e.changedTouches?.[0]?.clientX||0},{passive:true});shell.addEventListener('touchend',e=>{const x=e.changedTouches?.[0]?.clientX||0,d=x-readerTouchX;if(Math.abs(d)>52){if(d>0&&pageNo>1)void novelPage(pageNo-1);if(d<0&&pageNo<total)void novelPage(pageNo+1)}},{passive:true})}}
function renderLinearNovelUnavailable(){const n=state.novel||{},textRatio=n.total_pages?Math.min(1,(Number(n.generated_pages)||0)/Number(n.total_pages)):0,visualRatio=n.planned_images?Math.min(1,(Number(n.generated_images)||0)/Number(n.planned_images)):0,pct=Math.floor(Math.min(99,textRatio*75+visualRatio*25));root.innerHTML=frame(0,'Роман создаётся','Полная версия станет доступна здесь автоматически после генерации всех 100 страниц и иллюстраций.','<div class="waitCard"><div class="status"><i class="dot"></i>'+esc(n.status||'Подготовка')+' · '+Math.max(0,Math.min(99,pct))+'%</div></div>',secondary('Обновить','novelRefresh'));bind('#novelRefresh',safe(()=>novelPage(1)));poll=setTimeout(()=>novelPage(1).catch(()=>{}),5000)}
async function api(path,body={}){clearTimeout(poll);const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),35000);try{const data=initData();if(!data)throw new Error('TELEGRAM_AUTH_MISSING');const r=await fetch('/night/api/'+path,{method:'POST',headers:{'content-type':'application/json',...authHeaders()},body:JSON.stringify(body),signal:ctl.signal});const raw=await r.text();let d;try{d=JSON.parse(raw)}catch{throw new Error(r.ok?'NIGHT_RESPONSE_INVALID':'NIGHT_SERVICE_UNAVAILABLE')}if(!r.ok||!d.ok)throw new Error(d.error||'REQUEST_FAILED');state=d.state||state;if(state?.evening_mode){eveningMode=state.evening_mode;localStorage.setItem('night_evening_mode',eveningMode)}if(state?.ui_theme){uiTheme=state.ui_theme;localStorage.setItem('night_theme',uiTheme)}if(state?.mode!=='private_choice'){step=2;showMore=false}if(state?.mode!=='story_choice')storyStep=0;render();return d}catch(e){if(e?.name==='AbortError')throw new Error('Сервер не ответил. Попробуйте ещё раз');throw e}finally{clearTimeout(timer)}}function safe(fn,label=''){return async e=>{const el=e?.currentTarget,old=el?.innerHTML;try{if(el){el.disabled=true;if(label)el.textContent=label}haptic('light');await fn(e)}catch(err){if(el){el.disabled=false;if(label&&old)el.innerHTML=old}showError(err)}}}function showError(err){root.querySelectorAll('.notice.error').forEach(node=>node.remove());const box=document.createElement('div');box.className='notice error';box.textContent=humanError(err?.message||err);root.appendChild(box)}function schedule(ms=1800){clearTimeout(poll);poll=setTimeout(()=>api('bootstrap').catch(()=>schedule(2500)),ms)}
function choice(key,title,icon,selected,type,sub=''){return '<button type="button" class="choice '+(selected?'on':'')+'" data-'+type+'="'+esc(key)+'"><span class="choiceCopy"><b>'+esc(title||key)+'</b>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</span></button>'}
function permissionGrid(){const allowed=new Set(state.mode_permissions||Object.keys(perms));return '<div class="choiceGrid">'+Object.entries(perms).filter(([key])=>allowed.has(key)).map(([key,item])=>choice(key,item.title,item.icon,draft.permissions.includes(key),'perm')).join('')+'</div>'}
