if(state.test_mode)body='<div class="notice compactNotice"><div class="eyebrow">ИИ-ПАРТНЁР · СИМУЛЯЦИЯ</div><div class="micro">Второй участник уже заполнил свою приватную границу для теста.</div></div>'+body;
root.innerHTML=frame(step,title,lead,body,footer);
