all('[data-perm]',e=>e.onclick=()=>{const k=e.dataset.perm;draft.permissions=draft.permissions.includes(k)?draft.permissions.filter(x=>x!==k):[...draft.permissions,k];haptic();renderChoice()});
all('[data-tempo]',e=>e.onclick=()=>{draft.tempo=e.dataset.tempo;haptic();renderChoice()});
all('[data-level]',e=>e.onclick=()=>{draft.level=e.dataset.level;haptic();renderChoice()});
all('[data-bound]',e=>e.onclick=()=>{const k=e.dataset.bound;draft.boundaries=draft.boundaries.includes(k)?draft.boundaries.filter(x=>x!==k):[...draft.boundaries,k];haptic();renderChoice()});
bind('#next',()=>{if(step===2&&!draft.permissions.some(x=>physical.has(x)))return showError(new Error('Выберите хотя бы один телесный вариант'));if(step===3&&!draft.tempo)return showError(new Error('Выберите темп'));if(step===3&&!draft.level)return showError(new Error('Выберите уровень'));haptic('strong');step=Math.min(4,step+1);renderChoice()});
