const n=storyStep+5,title=storyStep===0?(interview.title||'Ваша история'):'Продолжите историю',lead=storyStep===0?'Это общий каркас. Ответ на вопрос видите только вы.':'ИИ собирает одну историю из двух приватных ответов.';
